import valueParser from "postcss-value-parser";
import { isMathFunction } from "../../reference/functions.js";
import { blankComments } from "../blankComments/index.js";
import { hideParenthesesInUrlStrings } from "../hideParenthesesInUrlStrings/index.js";
import { matchesStringOrRegExp } from "../matchesStringOrRegExp/index.js";
import { opensAnAddress } from "../opensAnAddress/index.js";
import { quotesItsAddress } from "../quotesItsAddress/index.js";
/**
 * Where a bare address's token closes, by PostCSS's tokenizer: every `(` and `)` counts, quoted or not, an escaped one does not. `postcss-value-parser` closes it on the first `)` and returns a solidus behind that as a divider.
 * @param text - The text, comments blanked.
 * @param openIndex - The index behind the `(`.
 * @returns The index behind the closing `)`, or the end of the text.
 */
function bareAddressEnd(text, openIndex) {
    let depth = 1;
    let index = openIndex;
    while (index < text.length && depth > 0) {
        let character = text.charAt(index);
        if (character === `\\`)
            index += 1;
        else if (character === `(`)
            depth += 1;
        else if (character === `)`)
            depth -= 1;
        index += 1;
    }
    return index;
}
/**
 * Finds every solidus separating two parts of a value: a ratio, a font shorthand, a grid area, an alpha.
 *
 * Comments are blanked first. Skipped with their contents: a `url()` address, a math function, a call the syntax does not read as one, and a call the options name. A nameless group is read as `readsGroups` says, and the syntax is asked at each solidus whether it is its own operator. The index is the solidus's own, not the `div` node's, which opens at the whitespace in front.
 * @param text - The text, as `Syntax#read` returns it.
 * @param syntax - The syntax asked about groups and operators.
 * @param node - The declaration or at-rule.
 * @param result - The Stylelint result.
 * @param options - What is read into and what is skipped.
 * @returns Each separator solidus, in order.
 */
export function findSeparatorSlashes(text, syntax, node, result, options) {
    let slashes = [];
    let comments = syntax.printedComments(node, text, result);
    let blanked = hideParenthesesInUrlStrings(blankComments(text, comments), comments);
    /**
     * Walks a list of nodes, into every call that is read.
     * @param nodes - The value-parser nodes of one level.
     */
    function walk(nodes) {
        // The end of a bare address's token; siblings made of its tail are skipped
        let addressEnd = 0;
        for (let [at, valueNode] of nodes.entries()) {
            if (valueNode.sourceIndex < addressEnd)
                continue;
            if (valueNode.type === `div`) {
                let index = valueNode.sourceIndex + valueNode.before.length;
                // `//` separates nothing, but the parser returns two dividers for it
                let pairsWithANeighbor = blanked.charAt(index - 1) === `/` || blanked.charAt(index + 1) === `/`;
                if (valueNode.value === `/` && !pairsWithANeighbor && !syntax.readsSlashAsOperator(nodes[at - 1], nodes[at + 1]))
                    slashes.push({ index });
                continue;
            }
            if (valueNode.type !== `function`)
                continue;
            if (valueNode.value === ``) {
                if (options.readsGroups)
                    walk(valueNode.nodes);
                continue;
            }
            // A bare address closes where the tokenizer says; a quoted one is a string among the arguments of a call, walked as any other
            if (opensAnAddress(valueNode, at, nodes) && !quotesItsAddress(valueNode)) {
                addressEnd = bareAddressEnd(blanked, valueNode.sourceIndex + valueNode.value.length + 1);
                continue;
            }
            if (!syntax.isStandardFunction(valueNode) || isMathFunction(valueNode.value))
                continue;
            if (options.ignoreFunctions !== undefined && matchesStringOrRegExp(valueNode.value, options.ignoreFunctions))
                continue;
            walk(valueNode.nodes);
        }
    }
    walk(valueParser(blanked).nodes);
    return slashes;
}
